<?php
defined('BASEPATH') or exit('No direct script access allowed');
$aColumns=['p.id','p.featured_image','p.post_title','c.category_name','w.name as website_name','l.name as language_name','p.views','p.status','p.created_at'];
$join=['LEFT JOIN '.db_prefix().'publishx_categories c ON c.id=p.category_id','LEFT JOIN '.db_prefix().'publishx_websites w ON w.id=p.website_id','LEFT JOIN '.db_prefix().'publishx_languages l ON l.id=p.language_id'];
$where=[];if(!has_permission('publishx_posts','','view'))$where[]='AND p.author_id='.(int)get_staff_user_id();
$r=data_tables_init($aColumns,'id',db_prefix().'publishx_posts p',$join,$where,['p.post_slug','p.published_url','p.author_id','p.featured_image_url']);$output=$r['output'];
foreach($r['rResult'] as $a){$row=[];$row[]=$a['id'];$postObj=(object)$a;$img=publishx_feature_image_url($postObj);$row[]='<img class="publishx-thumb" src="'.html_escape($img).'">';$row[]='<a href="'.admin_url('publishx/post/'.$a['id']).'"><strong>'.html_escape($a['post_title']).'</strong></a>';$row[]=html_escape($a['category_name']??'');$row[]=html_escape($a['website_name']??'');$row[]=html_escape($a['language_name']??'');$row[]=(int)$a['views'];$labels=[0=>'<span class="label label-success">'._l('publishx_published').'</span>',1=>'<span class="label label-default">'._l('publishx_draft').'</span>',2=>'<span class="label label-warning">'._l('publishx_scheduled').'</span>'];$row[]=$labels[(int)$a['status']]??'';$row[]=_dt($a['created_at']);$actions='<a class="btn btn-default btn-xs" href="'.admin_url('publishx/post/'.$a['id']).'"><i class="fa fa-edit"></i></a> ';if($a['published_url'])$actions.='<a target="_blank" class="btn btn-info btn-xs" href="'.html_escape($a['published_url']).'"><i class="fa fa-external-link"></i></a> ';if(has_permission('publishx_posts','','delete'))$actions.='<a class="btn btn-danger btn-xs _delete" href="'.admin_url('publishx/delete_post/'.$a['id']).'"><i class="fa fa-trash"></i></a>';$row[]=$actions;$output['aaData'][]=$row;}